  --color-text:         #e4e6f0;
  --color-text-muted:   #7c82a0;
  --color-accent:       #6c7bff;
  --color-accent-hover: #8a97ff;
  --color-danger:       #e05252;
  --color-danger-hover: #f06363;
  --color-danger-bg:    rgba(224, 82, 82, 0.12);
  --color-focus-ring:   #6c7bff;
  --radius-sm:          6px;
  --radius-md:          12px;
  --radius-lg:          18px;
  --shadow-card:        0 4px 24px rgba(0, 0, 0, 0.5);
  --shadow-dialog:      0 8px 48px rgba(0, 0, 0, 0.75);
  --transition:         180ms ease;
}

body {
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
}

/* ── Skip link ── */
.skip-link {
  position: absolute;
  top: -9999px;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--color-accent);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
}
.skip-link:focus { top: 1rem; }

/* ── Header ── */
header {
  width: 100%;
  padding: 1rem 2rem;
  border-bottom: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  gap: 0.75rem;
}
header h1 {
  font-size: 1.125rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.logo-icon {
  width: 28px; height: 28px;
  fill: var(--color-accent);
  flex-shrink: 0;
}

/* ── Main ── */
main {
  flex: 1;
  width: 100%;
  max-width: 680px;
  padding: 3rem 1.5rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;
}

/* ── Image card ── */
.image-card {
  width: 100%;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-card);
}

.image-wrapper {
  width: 100%;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  background: var(--color-surface-2);
  position: relative;
}

.image-wrapper img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.image-info {
  padding: 1.25rem 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}
.image-name {
  font-size: 1rem;
  font-weight: 600;
}
.image-meta {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
}

.image-actions {
  padding: 0 1.5rem 1.25rem;
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
}

/* ── Buttons ── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.5rem 1.125rem;
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  border: 1px solid transparent;
  transition: background var(--transition), color var(--transition),
              border-color var(--transition), box-shadow var(--transition);
  text-decoration: none;
  white-space: nowrap;
}
.btn:focus-visible {
  outline: 2px solid var(--color-focus-ring);
  outline-offset: 2px;
}

.btn-ghost {
  background: transparent;
  color: var(--color-text-muted);
  border-color: var(--color-border);
}
.btn-ghost:hover {
  background: var(--color-surface-2);
  color: var(--color-text);
}

